function hash(value,salt){return scryptSync(value,salt,32)}
function configured(){return Boolean(process.env.BOARD_PASSWORD_HASH&&process.env.BOARD_PASSWORD_SALT)||Boolean(process.env.BOARD_PASSWORD)}
function passwordOk(value){if(process.env.BOARD_PASSWORD_HASH&&process.env.BOARD_PASSWORD_SALT){const got=hash(value,process.env.BOARD_PASSWORD_SALT),expected=Buffer.from(process.env.BOARD_PASSWORD_HASH,'hex');return got.length===expected.length&&timingSafeEqual(got,expected)}return Boolean(process.env.BOARD_PASSWORD)&&value===process.env.BOARD_PASSWORD}
