async function keycloakLogin(username,password){const c=db.integrations.keycloak;if(!c.enabled||!c.url||!c.realm||!c.clientId)throw Error('Keycloak login is not configured');const form=new URLSearchParams({grant_type:'password',client_id:c.clientId,username,password,scope:'openid profile email'});if(c.clientSecret)form.set('client_secret',c.clientSecret);const endpoint=`${c.url.replace(/\/$/,'')}/realms/${encodeURIComponent(c.realm)}/protocol/openid-connect/token`,response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:form,signal:AbortSignal.timeout(15000)}),data=await response.json().catch(()=>({}));if(!response.ok)throw Error(response.status===401||response.status===400?'Username or password was not accepted.':data.error_description||`Keycloak returned ${response.status}`);let claims={};try{claims=JSON.parse(Buffer.from(data.access_token.split('.')[1],'base64url').toString())}catch{}return {name:claims.name||claims.preferred_username||username,username:claims.preferred_username||username,sub:claims.sub||'',role:keycloakRole(claims,c.clientId),keycloakTokenExpiresAt:Date.now()+Math.max(60,Number(data.expires_in||300))*1000,expiresAt:Date.now()+12*60*60*1000}}
function requireAuth(req,res){if(process.env.AUTH_BYPASS==='true')return {name:'Local preview',role:'admin'};const s=session(req);if(!s){json(res,401,{error:'Sign in required'});return null}return {...s,role:s.role||(s.bootstrap?'admin':'viewer')}}
