async function marketingTasks(){const c=db.integrations.vikunja;if(!c.url||!c.token)return {configured:false,tasks:[]};const headers={Authorization:`Bearer ${c.token}`,Accept:'application/json'},base=apiBase(c.url),projects=await fetchJson(`${base}/projects?per_page=100`,{headers},'Vikunja'),wanted=(Array.isArray(projects)?projects:[]).filter(project=>['night of the living loud','rage for democracy'].includes(String(project.title||'').toLowerCase())),tasks=[];for(const project of wanted){for(let page=1;page<=10;page++){const batch=await fetchJson(`${base}/projects/${project.id}/tasks?page=${page}&per_page=50`,{headers},'Vikunja marketing tasks');if(!Array.isArray(batch)||!batch.length)break;for(const task of batch){const labels=(task.labels||[]).map(label=>String(label.title||'').toLowerCase());if(labels.some(label=>label.includes('marketing')||label.includes('advertising')))tasks.push({id:task.id,title:task.title||'Untitled task',project:project.title,done:Boolean(task.done),dueDate:task.due_date||'',assignees:(task.assignees||[]).map(person=>person.username||person.name||`User ${person.id}`),labels:(task.labels||[]).map(label=>label.title),url:`${String(c.url).replace(/\/$/,'')}/tasks/${task.id}`})}if(batch.length<50)break}}return {configured:true,tasks:tasks.sort((a,b)=>Number(a.done)-Number(b.done)||String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')))}}
async function draftDonationLetter(payload,maxWords=220){const base=String(process.env.RFD_WRITER_URL||'').replace(/\/$/,'');if(!base)throw Error('Set RFD_WRITER_URL so the Hub can write the letter with the Rage assistant');const prompt=`Write a polished donation or sponsorship request letter for Rage for Democracy.\nRecipient/business: ${clean(payload.businessName)}\nPurpose: ${clean(payload.purpose)}\nEvent: ${clean(payload.eventName||payload.event_name)}\nEvent date: ${clean(payload.eventDate||payload.event_date)}\nSigner: ${clean(payload.signerName)}\nNotes: ${clean(payload.body).slice(0,1200)}\n\nThe complete letter must fit on one branded US Letter page. Keep it under ${maxWords} words including the greeting, closing, and signature. Prioritize the request and strongest supplied details; condense or omit secondary material. Use a professional, persuasive, community-focused voice. Include a greeting, clear request, why the support matters, and a gracious closing signed exactly as ${clean(payload.signerName)}. Do not invent contact information, titles, tax claims, statistics, or benefits not supplied. Return only the finished letter body in plain text. Do not call tools.`;let response;try{response=await fetch(`${base}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json',...(process.env.RFD_WRITER_TOKEN?{Authorization:`Bearer ${process.env.RFD_WRITER_TOKEN}`}:{})},body:JSON.stringify({model:process.env.RFD_WRITER_MODEL||'rage-assistant',stream:false,messages:[{role:'user',content:prompt}],temperature:.3}),signal:AbortSignal.timeout(180000)})}catch(error){throw Error(`Could not reach Rage writer at ${base}${error.cause?.code?` (${error.cause.code})`:''}`)}const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error?.message||data.error||`Rage writer returned ${response.status}`);const text=clean(data.choices?.[0]?.message?.content);if(!text)throw Error('Rage writer returned no letter text');return text}
async function generateDonationPdf(base,payload,letter){const response=await fetch(`${base}/generate-donation-letter`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,body:letter,recipient_name:payload.businessName,sender_name:payload.signerName,name:payload.signerName,post_to_outline:false,attach_pdf:false,one_page:true,max_pages:1,fit_to_page:true}),signal:AbortSignal.timeout(300000)});if(!response.ok)throw Error(`PDF generator returned ${response.status}: ${(await response.text()).slice(0,300)}`);const type=response.headers.get('content-type')||'';let bytes;if(type.includes('application/pdf'))bytes=Buffer.from(await response.arrayBuffer());else{const result=await response.json(),encoded=result.pdf_base64||result.pdfBase64,source=result.pdf_url||result.download_url||result.url||result.pdfUrl;if(encoded)bytes=Buffer.from(String(encoded).replace(/^data:[^;]+;base64,/,''),'base64');else if(source){const pdfResponse=await fetch(new URL(source,`${base}/`),{signal:AbortSignal.timeout(300000)});if(!pdfResponse.ok)throw Error(`Generated PDF download returned ${pdfResponse.status}`);bytes=Buffer.from(await pdfResponse.arrayBuffer())}else throw Error('PDF generator did not return a downloadable PDF')}if(!bytes?.length)throw Error('PDF generator returned an empty file');return bytes}
const pdfPageCount=bytes=>(bytes.toString('latin1').match(/\/Type\s*\/Page\b/g)||[]).length||1;
async function volunteerPdf(item,user){const base=String(process.env.PDF_GENERATOR_URL||'').replace(/\/$/,''),hours=(Number(item.minutes||0)/60).toFixed(2).replace(/\.00$/,''),signer=clean(item.verifiedBy||user.name),letter=`To whom it may concern,\n\nThis letter verifies that ${clean(item.name)} completed ${hours} volunteer hours supporting Rage for Democracy.\n\nService: ${clean(item.activity)}\nDate: ${clean(item.date)}${item.organization?`\nCrediting organization: ${clean(item.organization)}`:''}${item.notes?`\n\n${clean(item.notes)}`:''}\n\nSincerely,\n${signer}\nRage for Democracy`;const bytes=await generateDonationPdf(base,{businessName:item.name,purpose:'Volunteer Service Verification',eventName:item.organization||'Rage for Democracy',eventDate:item.date,signerName:signer},letter);await mkdir(join(DATA,'volunteer-pdfs'),{recursive:true});item.verificationStored=`${item.id}.pdf`;await writeFile(join(DATA,'volunteer-pdfs',item.verificationStored),bytes);item.verificationUpdatedAt=new Date().toISOString();await save();return bytes}
async function runPdfJob(job,payload){const base=String(process.env.PDF_GENERATOR_URL||'').replace(/\/$/,'');try{job.status='writing';job.progress=15;let letter=await draftDonationLetter(payload);job.status='generating';job.progress=55;let bytes=await generateDonationPdf(base,payload,letter);if(pdfPageCount(bytes)>1){job.status='writing';job.progress=68;letter=await draftDonationLetter(payload,160);job.status='generating';job.progress=78;bytes=await generateDonationPdf(base,payload,letter)}job.progress=90;if(pdfPageCount(bytes)>1)throw Error('The letter could not be fitted onto one page. Shorten the details and try again.');const dir=join(DATA,'generated-pdfs'),stored=`${job.id}.pdf`;await mkdir(dir,{recursive:true});await writeFile(join(dir,stored),bytes);Object.assign(job,{stored,name:`${clean(payload.businessName).replace(/[^a-z0-9 _-]/gi,'')||'donation-letter'}.pdf`,businessName:clean(payload.businessName),purpose:clean(payload.purpose),recipientEmail:clean(payload.recipientEmail),signerName:clean(payload.signerName),status:'ready',progress:100,completedAt:new Date().toISOString(),size:bytes.length,pages:1});db.generatedPdfs.unshift(job);db.generatedPdfs=db.generatedPdfs.slice(0,50);await save()}catch(error){job.status='failed';job.error=error.cause?.code?`Could not reach PDF generator at ${base} (${error.cause.code})`:error.message==='fetch failed'?`Could not reach PDF generator at ${base}`:error.message;job.progress=100}}
